// Regenerates .env.example from the ENV_VARS registry (names + descriptions, never values).
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { ENV_VARS } from "../packages/config/src/env";

const lines = [
  "# Suiem environment variables. Copy to .env (git-ignored) and fill in locally.",
  "# NAMES and DESCRIPTIONS only, never values (PRD §0.2 rule 10). Generated by `pnpm env:example`.",
  "",
];
for (const [name, description] of Object.entries(ENV_VARS))
  lines.push(`# ${description}`, `${name}=`, "");
writeFileSync(join(import.meta.dirname, "..", ".env.example"), lines.join("\n"));
console.log(`wrote .env.example (${Object.keys(ENV_VARS).length} variables)`);
